head.b:skin:
*,*::before,*::after{box-sizing:border-box}
html{scroll-behavior:smooth}
body{margin:0;padding:72px 0 0 0;font-family:'Inter',-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;font-size:16px;background-color:#0a0a0a!important;color:#fafaf9!important;-webkit-font-smoothing:antialiased}
body::before{content:"";position:fixed;inset:0;pointer-events:none;z-index:50;background-image:url('data:image/svg+xml;utf8,<svg viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg"><filter id="n"><feTurbulence type="fractalNoise" baseFrequency="0.65" numOctaves="3" stitchTiles="stitch"/></filter><rect width="100%" height="100%" filter="url(%23n)" opacity="0.04"/></svg>')}
h1,h2,h3,h4,h5,h6{font-family:'Inter',sans-serif;font-weight:300;letter-spacing:-0.025em;line-height:1}
.relative{position:relative}.absolute{position:absolute}.fixed{position:fixed}
.inset-0{inset:0;top:0;left:0;right:0;bottom:0}
.top-0{top:0}.bottom-0{bottom:0}.left-0{left:0}.right-0{right:0}
.top-2{top:0.5rem}.bottom-2{bottom:0.5rem}.left-2{left:0.5rem}.right-2{right:0.5rem}
.z-10{z-index:10}.z-20{z-index:20}.z-30{z-index:30}.z-50{z-index:50}
.inset-4{inset:1rem}.inset-8{inset:2rem}.inset-12{inset:3rem}.inset-16{inset:4rem}
.p-4{padding:1rem}.p-6{padding:1.5rem}.p-8{padding:2rem}
.px-4{padding-left:1rem;padding-right:1rem}.px-8{padding-left:2rem;padding-right:2rem}
.py-8{padding-top:2rem;padding-bottom:2rem}
.py-24{padding-top:6rem;padding-bottom:6rem}
.py-32{padding-top:8rem;padding-bottom:8rem}
.pt-4{padding-top:1rem}.pt-8{padding-top:2rem}.pt-12{padding-top:3rem}.pt-16{padding-top:4rem}
.pb-2{padding-bottom:0.5rem}.pb-8{padding-bottom:2rem}
.mt-2{margin-top:0.5rem}.mt-4{margin-top:1rem}.mt-8{margin-top:2rem}.mt-12{margin-top:3rem}.mt-16{margin-top:4rem}
.mb-2{margin-bottom:0.5rem}.mb-4{margin-bottom:1rem}.mb-6{margin-bottom:1.5rem}.mb-8{margin-bottom:2rem}.mb-12{margin-bottom:3rem}.mb-16{margin-bottom:4rem}.mb-24{margin-bottom:6rem}.mb-32{margin-bottom:8rem}
.mx-auto{margin-left:auto;margin-right:auto}
.-mt-8{margin-top:-2rem}.-mt-16{margin-top:-4rem}.-mt-24{margin-top:-6rem}
.w-full{width:100%}.w-3{width:0.75rem}.w-8{width:2rem}.w-px{width:1px}.w-max{width:max-content}
.h-full{height:100%}.h-3{height:0.75rem}.h-px{height:1px}
.max-w-3xl{max-width:48rem}.max-w-4xl{max-width:56rem}.max-w-6xl{max-width:72rem}.max-w-lg{max-width:32rem}.max-w-2xl{max-width:42rem}.max-w-xl{max-width:36rem}.max-w-90rem{max-width:90rem}
.overflow-hidden{overflow:hidden}
.pointer-events-none{pointer-events:none}.pointer-events-auto{pointer-events:auto}
.flex{display:flex}.inline-flex{display:inline-flex}.grid{display:grid}.block{display:block}.hidden{display:none}
.flex-col{flex-direction:column}.flex-row{flex-direction:row}.flex-wrap{flex-wrap:wrap}
.items-center{align-items:center}.items-start{align-items:flex-start}.items-end{align-items:flex-end}
.justify-center{justify-content:center}.justify-between{justify-content:space-between}
.flex-grow{flex-grow:1}.flex-1{flex:1}
.gap-1{gap:0.25rem}.gap-2{gap:0.5rem}.gap-4{gap:1rem}.gap-6{gap:1.5rem}.gap-8{gap:2rem}.gap-12{gap:3rem}.gap-16{gap:4rem}
.gap-x-2{column-gap:0.5rem}.gap-x-4{column-gap:1rem}.gap-x-6{column-gap:1.5rem}.gap-x-8{column-gap:2rem}.gap-x-12{column-gap:3rem}
.gap-y-2{row-gap:0.5rem}.gap-y-8{row-gap:2rem}
.col-span-1{grid-column:span 1}.col-span-2{grid-column:span 2}.col-span-4{grid-column:span 4}.col-span-5{grid-column:span 5}.col-span-6{grid-column:span 6}.col-span-7{grid-column:span 7}.col-span-8{grid-column:span 8}.col-span-12{grid-column:span 12}
.col-start-1{grid-column-start:1}.col-start-2{grid-column-start:2}.col-start-7{grid-column-start:7}.col-start-8{grid-column-start:8}.col-start-9{grid-column-start:9}
.grid-cols-1{grid-template-columns:repeat(1,minmax(0,1fr))}.grid-cols-2{grid-template-columns:repeat(2,minmax(0,1fr))}.grid-cols-12{grid-template-columns:repeat(12,minmax(0,1fr))}
.space-y-2>*+*{margin-top:0.5rem}.space-y-4>*+*{margin-top:1rem}.space-y-6>*+*{margin-top:1.5rem}.space-y-8>*+*{margin-top:2rem}
.order-1{order:1}.order-2{order:2}
.text-left{text-align:left}.text-right{text-align:right}.text-center{text-align:center}
.italic{font-style:italic}.uppercase{text-transform:uppercase}
.antialiased{-webkit-font-smoothing:antialiased}
.whitespace-nowrap{white-space:nowrap}
.leading-none{line-height:1}.leading-snug{line-height:1.375}.leading-relaxed{line-height:1.625}
.text-balance{text-wrap:balance}
.bg-0a0a0a{background-color:#0a0a0a}.bg-050505{background-color:#050505}
.bg-stone-100{background-color:#e8e2d8}.bg-stone-900\/10{background-color:rgba(58,54,46,0.1)}.bg-stone-900\/20{background-color:rgba(58,54,46,0.2)}.bg-stone-900\/90{background-color:rgba(10,10,10,0.9)}
.text-stone-50{color:#fafaf9}.text-stone-100{color:#e8e2d8}.text-stone-200{color:#d1c5b3}.text-stone-300{color:#b4a18e}.text-stone-400{color:#9a836e}.text-stone-500{color:#836d5a}.text-stone-600{color:#6e584a}
.border-stone-800\/20{border-color:rgba(90,70,60,0.2)}.border-stone-800\/30{border-color:rgba(90,70,60,0.3)}.border-stone-800\/40{border-color:rgba(90,70,60,0.4)}.border-stone-800{border-color:#4a3a33}.border-white\/5{border-color:rgba(255,255,255,0.05)}.border-white\/10{border-color:rgba(255,255,255,0.1)}.border-stone-700{border-color:#5a463c}.border-stone-500\/30{border-color:rgba(148,130,110,0.3)}
.text-stone-500\/20{color:rgba(131,109,90,0.2)}.text-stone-400\/70{color:rgba(154,131,110,0.7)}.text-stone-800\/50{color:rgba(90,70,60,0.5)}
.text-3xl{font-size:1.875rem}.text-4xl{font-size:2.25rem}.text-5xl{font-size:3rem}.text-xl{font-size:1.25rem}.text-lg{font-size:1.125rem}.text-base{font-size:1rem}.text-sm{font-size:0.875rem}.text-xs{font-size:0.75rem}.text-2xl{font-size:1.5rem}
.font-light{font-weight:300}.font-medium{font-weight:400}.font-semibold{font-weight:600}
.tracking-tight{letter-spacing:-0.025em}.tracking-wide{letter-spacing:0.05em}.tracking-widest{letter-spacing:0.15em}.tracking-\[0.2em\]{letter-spacing:0.2em}
.text-balance{text-wrap:balance}
.font-body{font-family:'Inter',sans-serif}.font-mono{font-family:'Courier New',monospace}
.object-contain{object-fit:contain}.object-cover{object-fit:cover}.filter{filter:var(--tw-filter)}.grayscale-\[15%\]{filter:grayscale(15%)}.grayscale-\[40%\]{filter:grayscale(40%)}.grayscale-\[5%\]{filter:grayscale(5%)}.contrast-110{filter:contrast(1.1)}.contrast-105{filter:contrast(1.05)}
.drop-shadow-2xl{filter:drop-shadow(0 20px 13px rgba(0,0,0,0.3))}
.backdrop-blur-sm{backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px)}
.rounded{border-radius:0.375rem}.rounded-sm{border-radius:2px}.rounded-full{border-radius:9999px}
.transition-all{transition:all 0.3s ease}.transition-colors{transition:color 0.3s ease,background-color 0.3s ease,border-color 0.3s ease}.transition-transform{transition:transform 0.3s ease}.transition-opacity{transition:opacity 0.3s ease}
.duration-200{transition-duration:200ms}.duration-300{transition-duration:300ms}.duration-500{transition-duration:500ms}
.ease-out{transition-timing-function:cubic-bezier(0.16,1,0.3,1)}
.hover\:bg-stone-300:hover{background-color:#d1c5b3}.hover\:bg-stone-100:hover{background-color:#e8e2d8}.hover\:text-stone-100:hover{color:#e8e2d8}.hover\:text-stone-300:hover{color:#b4a18e}.group:hover .group-hover\:translate-x-1{transform:translateX(0.25rem)}
.aspect-\[16\/10\]{aspect-ratio:16/10}.aspect-\[3\/4\]{aspect-ratio:3/4}.aspect-\[4\/3\]{aspect-ratio:4/3}.aspect-square{aspect-ratio:1/1}.aspect-\[16\/9\]{aspect-ratio:16/9}.aspect-\[4\/5\]{aspect-ratio:4/5}.aspect-\[21\/9\]{aspect-ratio:21/9}

/* LANGUAGE TOGGLE */
body[data-lang="en"] .lang-vi{display:none!important}
body[data-lang="en"] .lang-en{display:inline!important}
body[data-lang="vi"] .lang-vi{display:inline!important}
body[data-lang="vi"] .lang-en{display:none!important}

/* NAV LINKS — fix spacing */
.header-fixed{position:fixed;top:0;left:0;right:0;z-index:50;transition:all 0.5s ease;background-color:rgba(10,10,10,0.7);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);height:72px;display:flex;align-items:center}
.header-scrolled{background-color:rgba(10,10,10,0.95);backdrop-filter:blur(10px)}
.nav-link{font-size:0.75rem;font-weight:600;letter-spacing:0.15em;text-transform:uppercase;color:#9a836e;text-decoration:none;transition:color 0.3s ease;padding:0 0.5rem}
.nav-link:hover{color:#fafaf9}
.nav-divider{width:1px;height:4px;background-color:#4a3a33;margin:0 0.25rem}
.btn-primary{display:inline-flex;align-items:center;justify-content:center;padding:1rem 2rem;background-color:#e8e2d8;color:#0a0a0a;font-weight:500;font-size:0.875rem;letter-spacing:0.05em;transition:background-color 0.3s ease;text-decoration:none;cursor:pointer}
.btn-primary:hover{background-color:#d1c5b3}
.btn-secondary{display:inline-flex;align-items:center;justify-content:center;padding:1rem 2rem;border:1px solid #4a3a33;color:#d1c5b3;font-weight:500;font-size:0.875rem;letter-spacing:0.05em;transition:all 0.3s ease;text-decoration:none;cursor:pointer;background:transparent}
.btn-secondary:hover{background-color:#4a3a33}

/* PRODUCT CARDS — consistent spacing */
.product-card{display:flex;flex-direction:column;gap:1rem;transition:all 0.3s ease}
@media(min-width:768px){
.product-card{gap:1.5rem}
}
.product-card .product-image-wrap{position:relative;margin-bottom:1rem}
@media(min-width:768px){
.product-card .product-image-wrap{margin-bottom:1.5rem}
}
.product-card .product-info{display:flex;flex-direction:column;gap:0.5rem}

.tech-label-corner{position:absolute;font-size:0.625rem;text-transform:uppercase;letter-spacing:0.2em;padding:0.25rem 0.5rem;background-color:rgba(10,10,10,0.9);backdrop-filter:blur(8px);color:#9a836e;border:1px solid rgba(90,70,60,0.5);box-shadow:0 10px 15px -3px rgba(0,0,0,0.1);font-family:'Courier New',monospace;z-index:20;pointer-events:none;white-space:nowrap}
.tech-label-tl{top:0.5rem;left:0.5rem}.tech-label-br{bottom:0.5rem;right:0.5rem}
.product-frame-border{position:absolute;inset:-4px;border:1px solid rgba(90,70,60,0.2);pointer-events:none}
.product-corner-bracket{position:absolute;width:12px;height:12px;pointer-events:none}
.product-corner-tl{top:-1px;left:-1px;border-top:1px solid rgba(148,130,110,0.3);border-left:1px solid rgba(148,130,110,0.3)}
.product-corner-tr{top:-1px;right:-1px;border-top:1px solid rgba(148,130,110,0.3);border-right:1px solid rgba(148,130,110,0.3)}
.product-corner-bl{bottom:-1px;left:-1px;border-bottom:1px solid rgba(148,130,110,0.3);border-left:1px solid rgba(148,130,110,0.3)}
.product-corner-br{bottom:-1px;right:-1px;border-bottom:1px solid rgba(148,130,110,0.3);border-right:1px solid rgba(148,130,110,0.3)}
.product-cross-line{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;opacity:0.1;pointer-events:none}
.product-cross-line::before{content:"";width:1px;height:100%;background-color:#6e584a}
.section-label{display:inline-flex;align-items:center;gap:0.5rem;font-size:0.625rem;font-weight:600;letter-spacing:0.2em;text-transform:uppercase;color:#9a836e}
.section-label::before{content:"";display:block;width:2rem;height:1px;background-color:#4a3a33}
@keyframes spin{from{transform:rotate(0deg)}to{transform:rotate(360deg)}}
@keyframes fadeIn{from{opacity:0}to{opacity:1}}
@keyframes fadeInUp{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}
@keyframes scanLine{0%{top:0;opacity:0}10%{opacity:1}90%{opacity:1}100%{top:100%;opacity:0}}
@keyframes cornerPulse{0%,100%{opacity:0.35}50%{opacity:0.7}}
@keyframes floatUp{0%,100%{transform:translateY(0)}50%{transform:translateY(-4px)}}
.animate-spin{animation:spin 1s linear infinite}
.animate-fade-in{animation:fadeIn 0.8s ease-out}
.animate-fade-in-up{animation:fadeInUp 0.6s ease-out}
.animate-scan{animation:scanLine 4s linear infinite}
.animate-corner{animation:cornerPulse 3.5s ease-in-out infinite}
.animate-float{animation:floatUp 4s ease-in-out infinite}
.scan-line{position:absolute;left:0;right:0;height:1px;background-color:rgba(148,130,110,0.2);z-index:30;animation:scanLine 4s linear infinite}
.mobile-menu-overlay{position:fixed;inset:0;z-index:60;background-color:#0a0a0a;display:flex;flex-direction:column;padding:1.5rem}
#mobile-menu.hidden{display:none}
.lang-toggle{display:flex;align-items:center;gap:0.5rem;font-size:0.75rem;font-weight:600;letter-spacing:0.15em}
.lang-btn{cursor:pointer;color:#9a836e;transition:color 0.2s ease;background:none;border:none;padding:0;font-size:inherit;font-family:inherit}
.lang-btn:hover{color:#fafaf9}.lang-btn-active{color:#fafaf9}
.lang-separator{color:#4a3a33}
.hero-section{min-height:100svh;background-color:#0a0a0a;padding-top:72px;padding-bottom:4rem;display:flex;flex-direction:column;justify-content:center;overflow:hidden}
.launcher-section{position:relative;padding-top:6rem;padding-bottom:8rem;background-color:#050505;overflow:hidden}
.footer-section{padding-top:2rem;padding-bottom:2rem;background-color:#0a0a0a;border-top:1px solid rgba(90,70,60,0.3)}
.facebook-btn{display:inline-flex;align-items:center;justify-content:center;padding:0.75rem 1.5rem;background-color:#1877F2;color:#fff;font-weight:500;font-size:0.875rem;letter-spacing:0.05em;text-decoration:none;transition:background-color 0.3s ease;border-radius:0.375rem;cursor:pointer}
.facebook-btn:hover{background-color:#166fe5}
::-webkit-scrollbar{width:8px}::-webkit-scrollbar-track{background:#0a0a0a}::-webkit-scrollbar-thumb{background:#4a3a33}::-webkit-scrollbar-thumb:hover{background:#5a463c}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:0.01ms!important;transition-duration:0.01ms!important}html{scroll-behavior:auto}}

body.script:
(function() {
  var viData = {
    "layout":{"navHeight":"72px","heroHeight":"100svh","baseFontSize":"16px"},
    "nav":{"projects":"Dự án","launcher":"9Flip","about":"Giới thiệu","contact":"Liên hệ"},
    "hero":{"headline":"Công nghệ được làm lại theo cách thiết thực hơn.","subheadline":"Phần mềm và những dự án phần cứng độc bản","cta":"KHÁM PHÁ SẢN PHẨM"},
    "launcher":{"sectionTitle":"PHẦN MỀM NỔI BẬT","title":"9 Flip Launcher","description":"Mở ứng dụng trên màn hình ngoài Galaxy Z Flip.","trust":["NO ROOT","GOOGLE PLAY","NO ADS","NO DATA COLLECTION"],"features":[{"title":"Không Root","desc":"Giữ nguyên bảo hành, Knox nguyên vẹn."},{"title":"Dễ cài đặt","desc":"Có sẵn trên Google Play."},{"title":"Tài khoản Google","desc":"Premium theo tài khoản."},{"title":"Cộng đồng lớn","desc":"Cộng đồng đông đảo."}],"cta":"TẢI TRÊN GOOGLE PLAY"},
    "products":{"sectionTitle":"DỰ ÁN PHẦN CỨNG","viewDetails":"Xem chi tiết"},
    "footer":{"copyright":"Mixed Technology"}
  };
  var enData = {
    "layout":{"navHeight":"72px","heroHeight":"100svh","baseFontSize":"16px"},
    "nav":{"projects":"Projects","launcher":"9Flip","about":"About","contact":"Contact"},
    "hero":{"headline":"Technology re-engineered for practical use.","subheadline":"Software solutions and bespoke hardware modifications for those who want more from their devices.","cta":"EXPLORE PRODUCTS"},
    "launcher":{"sectionTitle":"FEATURED SOFTWARE","title":"9 Flip Launcher","description":"Launch apps on your Galaxy Z Flip cover screen.","trust":["NO ROOT","GOOGLE PLAY","NO ADS","NO DATA COLLECTION"],"features":[{"title":"No Root Required","desc":"Keeps your warranty and Knox intact."},{"title":"Easy Installation","desc":"Available on Google Play, ready in minutes."},{"title":"Google Account","desc":"Premium tied to your account."},{"title":"Large Community","desc":"Active community and continuous updates."}],"cta":"GET IT ON GOOGLE PLAY"},
    "products":{"sectionTitle":"HARDWARE PROJECTS","viewDetails":"View details"},
    "footer":{"copyright":"Mixed Technology"}
  };
  var currentLang = localStorage.getItem('mixed_lang') || 'vi';
  function setLang(lang) {
    localStorage.setItem('mixed_lang', lang);
    document.body.setAttribute('data-lang', lang);
    var viBtn = document.getElementById('lang-vi');
    var enBtn = document.getElementById('lang-en');
    if (viBtn) viBtn.className = 'lang-btn' + (lang === 'vi' ? ' lang-btn-active' : '');
    if (enBtn) enBtn.className = 'lang-btn' + (lang === 'en' ? ' lang-btn-active' : '');
  }
  setLang(currentLang);
  window.toggleMobileMenu = function() { var m = document.getElementById('mobile-menu'); if (m) m.classList.toggle('hidden'); };
  window.addEventListener('scroll', function() { var h = document.getElementById('header'); if (h) { if (window.scrollY > 20) h.classList.add('header-scrolled'); else h.classList.remove('header-scrolled'); } });
})();
